# -*- coding: utf-8 -*-
from _lib import *
MM='Manuel des Monstres 5e (2014)'
I(1,'Dans D&D 5e, lequel de ces monstres n’est pas un mort-vivant ?','Golem de chair',['Zombie','Squelette','Goule'],'Le golem de chair est une créature artificielle (artificiel). Zombie, squelette et goule sont des morts-vivants.',MM+', entrées « Golem de chair », « Zombie », « Squelette », « Goule »')
I(3,'Dans D&D 5e, lequel de ces sorts n’est pas un sort de nécromancie ?','Détection du mal et du bien',['Animation des morts','Communication avec les morts','Flétrissure'],'Détection du mal et du bien appartient à l’école de divination ; les trois autres sont des sorts de nécromancie.',"Manuel des Joueurs 5e (2014), chapitre « Sorts »")
I(2,'Parmi ces personnages de D&D, lequel n’est pas une liche ?','Strahd von Zarovich',['Acererak','Vecna','Szass Tam'],'Strahd est un vampire. Acererak, Vecna et Szass Tam sont des liches.',"Curse of Strahd (2016), Tomb of Annihilation (2017), Dungeon Master’s Guide 5e (2014)")
T(1,'Dans D&D 5e, une liche lie son âme à un ____ pour pouvoir se reformer après sa destruction.','phylactère',['sarcophage','grimoire','cristal de focalisation'],'Le phylactère contient l’âme de la liche : tant qu’il n’est pas détruit, elle se reforme.',MM+', entrée « Liche »')
T(2,'Dans D&D 5e, le seigneur vampire Strahd règne sur la ____.','Barovie',['Sembie','Thay','Cormyr'],'Strahd von Zarovich est le maître de la Barovie, un domaine de brumes de l’aventure Curse of Strahd.',"Curse of Strahd (2016)")
T(1,'Dans D&D 5e, les momies sont particulièrement vulnérables au ____.','feu',['froid','acide','tonnerre'],'La momie est vulnérable au feu : une torche ou un sort de flammes la fait brûler comme des bandelettes sèches.',MM+', entrée « Momie »')
M(1,'Dans D&D 5e, lesquels de ces monstres sont des morts-vivants ? (plusieurs bonnes réponses)',['Zombie','Momie','Spectre'],['Gargouille','Golem de fer'],'Zombie, momie et spectre sont des morts-vivants. La gargouille est un élémentaire et le golem de fer une créature artificielle.',MM+', entrées correspondantes')
M(2,'Dans D&D 5e, lesquels de ces morts-vivants sont incorporels ? (plusieurs bonnes réponses)',['Spectre','Fantôme','Banshee'],['Goule','Momie'],'Spectre, fantôme et banshee peuvent traverser les objets. La goule et la momie ont un corps bien solide.',MM+', entrées correspondantes')
M(3,'Dans D&D 5e, quelles sont de vraies faiblesses du vampire (d’après son profil) ? (plusieurs bonnes réponses)',['Lumière du soleil','Eau courante','Pieu dans le cœur'],['Ail','Argent'],'Le profil du vampire 5e inclut hypersensibilité au soleil, dégâts dans l’eau courante et pieu dans le cœur. L’ail et l’argent n’y figurent pas.',MM+', entrée « Vampire »')
O(2,'Classe ces morts-vivants par FP croissant (du moins dangereux au plus dangereux).',['Squelette','Momie','Spectre','Vampire','Liche'],'FP : squelette 1/4, momie 3, spectre 5, vampire 13, liche 21.',MM+', blocs de caractéristiques')
O(3,'Classe ces publications dans l’ordre chronologique de leur parution.',['La Tombe des Horreurs','Ravenloft','Curse of Strahd','Tomb of Annihilation'],'1978 (Tombe des Horreurs), 1983 (Ravenloft), 2016 (Curse of Strahd), 2017 (Tomb of Annihilation).','Historique des modules D&D (TSR / Wizards of the Coast)')
A(1,'Associe chaque mort-vivant à sa capacité caractéristique.',[('Goule','Griffes paralysantes'),('Banshee','Hurlement mortel'),('Fantôme','Possession'),('Liche','Phylactère')],'Chaque mort-vivant a sa marque : paralysie, hurlement, possession et phylactère.',MM+', entrées correspondantes')
A(2,'Associe chaque personnage à son domaine ou à sa création.',[('Strahd','Barovie'),('Acererak','Tombe des Horreurs'),('Szass Tam','Thay'),('Vecna','Main et Œil')],'Strahd règne sur la Barovie, Acererak a bâti la Tombe des Horreurs, Szass Tam dirige Thay, et la Main et l’Œil sont les reliques de Vecna.','Curse of Strahd, Tomb of Annihilation, Dungeon Master’s Guide 5e')
W(1,['Je suis un mort-vivant d’apparence humaine.','Le soleil me blesse et l’eau courante me nuit.','Je me nourris de sang et peux me changer en chauve-souris, en loup ou en brume.'],'Vampire',['Goule','Liche','Spectre'],'Le vampire est un mort-vivant aristocratique, aux nombreuses faiblesses.',MM+', entrée « Vampire »')
W(2,['J’étais un puissant lanceur de sorts.','J’ai renoncé à la vie par un sombre rituel.','Mon âme est cachée dans un phylactère.'],'Liche',['Vampire','Chevalier de la mort','Seigneur momie'],'La liche est un magicien devenu mort-vivant pour échapper à la mort.',MM+', entrée « Liche »')
W(3,['Je suis l’esprit tourmenté d’une elfe malfaisante.','Je suis incorporelle et je hante les lieux de ma mort.','Mon hurlement peut tuer d’un coup.'],'Banshee',['Spectre','Fantôme','Revenant'],'La banshee est l’esprit d’une elfe maléfique ; son hurlement mortel est sa capacité la plus redoutée.',MM+', entrée « Banshee »')
W(2,['Je suis revenu d’entre les morts.','Je poursuis un seul but, la vengeance.','Je ne m’arrête que lorsque mon meurtrier est mort.'],'Revenant',['Zombie','Momie','Goule'],'Le revenant se relève de sa tombe pour traquer celui qui l’a assassiné.',MM+', entrée « Revenant »')
save('morts-vivants-dnd','mor')
